package com.api.server

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.nio.ByteBuffer
import java.util.concurrent.ConcurrentHashMap

object ManagedMemoryPool {
  private val poolSize: Int = 4096
  private val pool: ByteBuffer = ByteBuffer.allocateDirect(poolSize)
  private var offset: Int = 0

  def allocate(size: Int): Option[ByteBuffer] = synchronized {
    if (size <= 0 || size > poolSize) return None
    if (offset + size > poolSize) {
      offset = 0 // wrap around - reuse pool
    }
    val slice = pool.duplicate()
    slice.position(offset)
    slice.limit(offset + size)
    offset += size
    Some(slice.slice())
  }

  def write(buffer: ByteBuffer, data: Array[Byte], maxLen: Int): Int = {
    val writeLen = math.min(data.length, math.min(maxLen, buffer.remaining()))
    buffer.put(data, 0, writeLen)
    writeLen
  }

  def read(buffer: ByteBuffer, length: Int): Array[Byte] = {
    buffer.flip()
    val readLen = math.min(length, buffer.remaining())
    val result = new Array[Byte](readLen)
    buffer.get(result, 0, readLen)
    result
  }
}

case class RequestContext(sessionId: String, payload: Array[Byte], callbackId: String)

trait RequestHandler {
  def handle(ctx: RequestContext)(implicit ec: ExecutionContext): Future[Array[Byte]]
}

class BoundedBufferHandler extends RequestHandler {
  private val maxPayloadSize = 256
  private val headerSize = 8
  private val totalBufferSize = maxPayloadSize + headerSize

  override def handle(ctx: RequestContext)(implicit ec: ExecutionContext): Future[Array[Byte]] = Future {
    ManagedMemoryPool.allocate(totalBufferSize) match {
      case None => throw new RuntimeException("Pool exhausted")
      case Some(buffer) =>
        // Write header (contains callback identifier for async completion)
        val callbackBytes = ctx.callbackId.getBytes("UTF-8").take(headerSize)
        ManagedMemoryPool.write(buffer, callbackBytes, headerSize)

        // Write payload with strict bounds enforcement
        // ByteBuffer.remaining() prevents any overflow beyond allocated region
        val written = ManagedMemoryPool.write(buffer, ctx.payload, maxPayloadSize)

        // Read back processed data
        ManagedMemoryPool.read(buffer, written)
    }
  }
}

class AsyncDispatcher {
  private val handlers = Map[String, RequestHandler](
    "process" -> new BoundedBufferHandler()
  )

  private val completionCallbacks = new ConcurrentHashMap[String, String]()

  def registerCallback(sessionId: String, callbackId: String): Unit = {
    // Validate callback ID format
    if (callbackId.matches("[a-zA-Z0-9\\-]{1,64}")) {
      completionCallbacks.put(sessionId, callbackId)
    }
  }

  def dispatch(route: String, sessionId: String, payload: Array[Byte]): Future[Array[Byte]] = {
    val callbackId = completionCallbacks.getOrDefault(sessionId, "default")
    val ctx = RequestContext(sessionId, payload, callbackId)

    handlers.get(route) match {
      case Some(handler) => handler.handle(ctx)
      case None => Future.failed(new RuntimeException(s"No handler for $route"))
    }
  }
}

object ApiServer {
  val dispatcher = new AsyncDispatcher()

  def handleRequest(route: String, sessionId: String, rawPayload: Array[Byte]): Future[Array[Byte]] = {
    // Validate session exists
    if (sessionId == null || sessionId.isEmpty) {
      return Future.failed(new IllegalArgumentException("Invalid session"))
    }

    // Session ID format validation
    if (!sessionId.matches("[a-zA-Z0-9\\-]{1,128}")) {
      return Future.failed(new IllegalArgumentException("Invalid session format"))
    }

    // Route validation
    if (!route.matches("[a-z]+")) {
      return Future.failed(new IllegalArgumentException("Invalid route"))
    }

    // Payload size validation at entry point
    if (rawPayload == null || rawPayload.length > 256) {
      return Future.failed(new IllegalArgumentException("Payload too large"))
    }

    dispatcher.dispatch(route, sessionId, rawPayload)
  }

  def main(args: Array[String]): Unit = {
    dispatcher.registerCallback("session-1", "cb-handler-1")

    // Simulate normal request
    val normalPayload = "Hello, World!".getBytes
    handleRequest("process", "session-1", normalPayload)
  }
}
